// 636 chars
#define L(a, b) abs((a).x * normalize(b).y - (a).y * normalize(b).x)
void mainImage(out vec4 O, vec2 U) {
        O = vec4(0);
        vec2 R = iResolution.xy,
                u = (U + U - R) / R.y, v;
        vec2 a, b, c, d, e;
        float r = 15., f = r * .5, h = f * sqrt(3.) / 3., type, i;
        a = vec2(0, h + h);
        b = vec2(-f, -h);
        c = vec2(f, -h);
        vec2 na, nb, nc;
        for (i = 0.; i < 9.; i++) {
                if (type < .5) {
                        d = (a + b + c) / 3.;
                        type = 1.;
                        if (dot(u - d, a - b) > 0. && dot(u - d, c - b) > 0.) b = a;
                        else if (dot(u - d, a - c) > 0.) c = a;
                        a = d;
                } else {
                        d = b + (c - b) / 3.;
                        e = b + c - d;
                        if (dot(u - a, c - a) < 0.) c = a, a = d;
                        else if (dot(u - a, a - b) > 0.) b = a, a = e;
                        else type = 0., b = d, c = e;
                }
        }
        float s = 1e8;
        s = min(s, L(u - c, a - c));
        s = min(s, L(u - a, b - a));
        s = min(s, L(u - b, c - b));
        if (type < .5) {
                O.z += .6;
                s /= length(a-b);
        } else {
                O.xy += .6;
                s /= length(b-c);
        }

        O -= vec4(smoothstep(.05, 0., s));
}


